// Fortschritt einer Aufgabe – Prüfung der Anfrage der Oberfläche:
//   { tache_id }                  eine bestimmte Aufgabe (UUID-Kennung)
//   { etage, recent: true }       der letzte Etagenbericht der letzten 16 Stunden (z. B. der von 5:30 Uhr)
const e = $input.first().json?.body ?? {};
if (e.recent === true) {
  const etage = Number(e.etage);
  if (!Number.isInteger(etage) || etage < 0 || etage > 20) throw new Error('Ungültige Etage');
  return [{ json: { tache_id: '', etage: String(etage) } }];
}
const id = String(e.tache_id ?? '');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) throw new Error('Ungültige tache_id');
return [{ json: { tache_id: id, etage: '' } }];

// Fortschritt einer Aufgabe – Antwort an die Oberfläche.
const demande = $('Aufgabe prüfen').first().json;
const t = $input.first().json ?? {};
if (!t.id) {
  if (demande.etage) return [{ json: { tache_id: null } }]; // « der letzte Bericht der Etage »: Es gibt keinen
  throw new Error('Aufgabe nicht gefunden');
}
return [
  {
    json: {
      tache_id: t.id,
      type: t.type,
      statut: t.statut,
      total: t.total,
      fait: t.fait,
      automatique: t.parametres?.automatique === true,
      cree_le: t.cree_le,
      resultat: t.resultat ?? [],
    },
  },
];

// Sitzungsprüfung – das « Bearer »-Token im Authorization-Header (43 URL-sichere Zeichen) wird gehasht (SHA-256): Nur der Hash steht in der Datenbank.
const entetes = $input.first().json?.headers ?? {};
const m = String(entetes.authorization ?? '').match(/^Bearer ([A-Za-z0-9_-]{43})$/);
if (!m) return [{ json: { hash: '' } }];
return [{ json: { hash: require('crypto').createHash('sha256').update(m[1]).digest('hex') } }];

// Sitzungsprüfung – Ergebnis: eine identifizierte Pflegekraft (Sitzung offen, nicht abgelaufen, Konto aktiv) oder nichts.
const r = $input.first().json ?? {};
if (!r.identifiant) return [{ json: { ok: false } }];
return [{ json: { ok: true, soignant: { identifiant: r.identifiant, nom: r.nom }, jeton_hash: r.jeton_hash } }];
